data = {
 'Delta': (61643,5995,3457),
 'United': (57063,5096,3149),
 'Southwest': (27483,321,465),
 'American': (54211,2614,846),
 'Alaska': (11735,570,395),
}
op_margin = {}
net_margin = {}
for k,(rev,op,net) in data.items():
    op_margin[k]=op/rev*100
    net_margin[k]=net/rev*100

print("Operating margin:")
for k,v in sorted(op_margin.items(), key=lambda x:-x[1]):
    print(k, round(v,2))
print("\nNet margin:")
for k,v in sorted(net_margin.items(), key=lambda x:-x[1]):
    print(k, round(v,2))

